CREATE VIRTUAL TABLE IF NOT EXISTS Entries_fts USING fts5(
    Id UNINDEXED,
    SessionId UNINDEXED,
    Role UNINDEXED,
    Content
);

-- Keyed by rowid, not by the UNINDEXED Id column: FTS5 can only satisfy MATCH, rowid and rank
-- constraints, so `WHERE Id = old.Id` scans the entire index once per deleted entry, which makes a
-- session purge or an entry-retention sweep quadratic.
CREATE TRIGGER IF NOT EXISTS Entries_ad AFTER DELETE ON Entries BEGIN
    DELETE FROM Entries_fts WHERE rowid = old.rowid;
END;

-- Keyed by rowid for the same reason as Entries_ad: an equality on the UNINDEXED Id column costs a
-- full scan of Entries_fts on every entry update.
CREATE TRIGGER IF NOT EXISTS Entries_au AFTER UPDATE ON Entries BEGIN
    DELETE FROM Entries_fts WHERE rowid = old.rowid;

    INSERT INTO Entries_fts(rowid, Id, SessionId, Role, Content)
    VALUES (new.rowid, new.Id, new.SessionId, new.Role, new.Content);
END;

